def annotated(response: Annotated[Response, Depends(modify_response)]):
    assert isinstance(response, Response)
    response.status_code = 201
    return {'ok': True}

@app.get('/default')
def default(response: Response = Depends(modify_response)):
    assert isinstance(response, Response)
    response.status_code = 202
    return {'ok': True}

